<?php
if(!defined('ABSPATH')){exit;}
final class WGPP_FB_Reports {
    public static function chunks($ranges){$jobs=[];foreach($ranges as $side=>$range){if(!$range){continue;}$from=WGPP_Analytics::date($range[0]);$end=WGPP_Analytics::date($range[1]);while($from<=$end){$until=min($from->modify('+29 days'),$end);$jobs[]=['side'=>$side,'from'=>$from->format('Y-m-d'),'to'=>$until->format('Y-m-d')];$from=$until->modify('+1 day');}}return $jobs;}
    public static function parse($body,$from,$to,$metricName=WGPP_Facebook::METRIC){
        if(!is_array($body['data'] ?? null)){throw new RuntimeException('Unexpected Facebook insight response.');}$series=null;
        foreach($body['data'] as $metric){if(($metric['name'] ?? '')!==$metricName || ($metric['period'] ?? '')!=='day'){continue;}if(!is_array($metric['values'] ?? null)){throw new RuntimeException('Facebook did not provide daily values.');}$series=[];
            foreach($metric['values'] as $r){$value=$r['value'] ?? null;$stamp=$r['end_time'] ?? null;if(!is_numeric($value) || !is_finite((float)$value) || $value<0 || !is_string($stamp) || !preg_match('/^\d{4}-\d{2}-\d{2}T/',$stamp)){throw new RuntimeException('Unexpected Facebook daily metric value.');}
                try{$end=new DateTimeImmutable($stamp);}catch(Exception $e){throw new RuntimeException('Invalid Facebook reporting timestamp.');}$date=$end->modify('-1 day')->format('Y-m-d');if($date>=$from && $date<=$to){$series[$date]=['date'=>$date,'value'=>(float)$value,'end_time'=>$stamp];}}
        }if($series===null){throw new RuntimeException('Facebook did not return the pilot metric. Check Page insights access and metric availability.');}if(!empty($body['paging']['next'])){$expected=(int)WGPP_Analytics::date($from)->diff(WGPP_Analytics::date($to))->format('%a')+1;if(count($series)!==$expected){throw new RuntimeException('Facebook returned an incomplete insight response. Narrow the reporting dates.');}}return $series;
    }
    public static function summary($points,$range,$followers=false){
        ksort($points);$days=(int)WGPP_Analytics::date($range[0])->diff(WGPP_Analytics::date($range[1]))->format('%a')+1;
        if($followers){$before=WGPP_Analytics::date($range[0])->modify('-1 day')->format('Y-m-d');$start=$points[$before]['value'] ?? null;$end=$points[$range[1]]['value'] ?? null;return ['total'=>$end,'net'=>$start!==null && $end!==null?$end-$start:null,'change'=>$start!==null && $end!==null?WGPP_Analytics::percent($end,$start):null];}
        return ['total'=>count($points)===$days?array_sum(array_column($points,'value')):null,'reported_days'=>count($points),'requested_days'=>$days];
    }
    public static function excerpt($text){preg_match('/^.{0,240}/us',(string)$text,$match);return $match[0] ?? 'Facebook post';}
    public static function post_rows($body,$range){
        if(!is_array($body['data'] ?? null)){throw new RuntimeException('Facebook did not provide posts.');}$rows=[];
        foreach($body['data'] as $post){$id=$post['id'] ?? '';if(!is_string($id) || !preg_match('/^[0-9]+_[0-9]+$/D',$id)){throw new RuntimeException('Invalid Facebook post identifier.');}
            $stamp=$post['created_time'] ?? '';try{$d=new DateTimeImmutable($stamp);}catch(Exception $e){throw new RuntimeException('Invalid Facebook post date.');}$date=$d->format('Y-m-d');if($date<$range[0] || $date>$range[1]){continue;}
            $value=null;foreach(($post['insights']['data'] ?? []) as $metric){if(($metric['name'] ?? '')==='post_media_view' && ($metric['period'] ?? '')==='lifetime'){$v=$metric['values'][0]['value'] ?? null;if(is_numeric($v) && is_finite((float)$v) && $v>=0){$value=(float)$v;}}}
            $url=$post['permalink_url'] ?? '';$host=parse_url($url,PHP_URL_HOST);if(parse_url($url,PHP_URL_SCHEME)!=='https' || !in_array($host,['facebook.com','www.facebook.com','m.facebook.com'],true)){$url='';}
            $rows[$id]=['id'=>$id,'date'=>$date,'text'=>self::excerpt($post['message'] ?? 'Facebook post'),'url'=>$url,'views'=>$value];
        }return $rows;
    }
    public static function result($job){$output=['status'=>'complete','page'=>$job['name'],'ranges'=>$job['ranges'],'collected_at'=>gmdate('c',$job['updated']),'errors'=>$job['errors'] ?? []];
        foreach(['current','comparison'] as $side){if(!$job['ranges'][$side]){$output[$side]=null;continue;}$output[$side]=['views'=>self::summary($job['series']['page_media_view'][$side] ?? [],$job['ranges'][$side]),'followers'=>self::summary($job['series']['page_follows'][$side] ?? [],$job['ranges'][$side],true)];}
        $output['change']=$output['comparison'] && $output['current']['views']['total']!==null && $output['comparison']['views']['total']!==null?WGPP_Analytics::percent($output['current']['views']['total'],$output['comparison']['views']['total']):null;
        $posts=array_values($job['posts'] ?? []);$valid=array_values(array_filter($posts,static function($p){return $p['views']!==null;}));usort($valid,static function($a,$b){return ($b['views']<=>$a['views']) ?: strcmp($a['id'],$b['id']);});$output['posts']=['top'=>array_slice($valid,0,5),'lower'=>array_slice(array_reverse(array_slice($valid,5)),0,5),'engagement_basis'=>'Engagement actions are not supplied; views measure visibility, not reactions, comments, shares or saves.','count'=>count($posts),'ranked'=>count($valid),'complete'=>empty($job['posts_incomplete']) && count($valid)===count($posts) && empty($job['errors']['posts'])];return $output;
    }
    public static function request($company,$ranges){
        if(!WGPP_Company::can('view') || (int)(WGPP_Company::context()['id'] ?? 0)!==(int)$company){throw new RuntimeException('Company access required.');}
        $saved=get_post_meta($company,WGPP_Facebook::PAGE,true);if(!$saved){return ['status'=>'not_connected','message'=>'Connect and select the company Facebook Page under Account → Connections.'];}
        $app=WGPP_Facebook::app();$page=WGPP_Facebook::decrypt($saved,'company:'.$company.':page');if(($page['app'] ?? '')!==WGPP_Facebook::signature($app)){throw new RuntimeException('Meta application settings changed. Reconnect Facebook.');}
        foreach($ranges as $range){if(!$range){continue;}$days=(int)WGPP_Analytics::date($range[0])->diff(WGPP_Analytics::date($range[1]))->format('%r%a')+1;if($days<1 || $days>366){throw new InvalidArgumentException('The Facebook pilot supports up to one year per reporting period.');}}
        $key=hash('sha256',wp_json_encode($ranges).'|views-followers-posts-v1|'.$page['grant']);$jobs=[];foreach(['page_media_view','page_follows'] as $metric){$metricRanges=$ranges;if($metric==='page_follows'){foreach($metricRanges as &$r){if($r){$r[0]=WGPP_Analytics::date($r[0])->modify('-1 day')->format('Y-m-d');}}unset($r);}foreach(self::chunks($metricRanges) as $task){$task['metric']=$metric;$jobs[]=$task;}}$jobs[]=['metric'=>'posts','from'=>$ranges['current'][0],'to'=>$ranges['current'][1]];
        $job=WGPP_Native_Reviews::locked($company,static function()use($company,$key,$jobs,$page,$ranges){$cache=get_post_meta($company,WGPP_Facebook::CACHE,true) ?: [];$entry=$cache[$key] ?? null;
            if($entry && $entry['status']==='complete' && $entry['updated']>time()-21600){return ['done'=>$entry];}
            if($entry && $entry['status']==='failed' && $entry['updated']>time()-300){return ['failed'=>$entry['message']];}
            if($entry && $entry['status']==='processing' && $entry['updated']>time()-60){return null;}
            if(!$entry || $entry['updated']<time()-21600 || $entry['status']==='failed'){$entry=['step'=>0,'series'=>[],'posts'=>[],'jobs'=>$jobs,'errors'=>[],'ranges'=>$ranges,'name'=>$page['name']];}
            if(count($cache)>=12 && !isset($cache[$key])){uasort($cache,static function($a,$b){return $a['updated']<=>$b['updated'];});unset($cache[array_key_first($cache)]);}
            $entry['status']='processing';$entry['updated']=time();$cache[$key]=$entry;WGPP_Facebook::save_meta($company,WGPP_Facebook::CACHE,$cache);return $entry;
        });
        if($job===null){return ['status'=>'queued'];}if(isset($job['done'])){return self::result($job['done']);}if(isset($job['failed'])){return ['status'=>'failed','message'=>$job['failed'].' Retry after five minutes, or reconnect if authorization changed.'];}
        try{$jobs=$job['jobs'];$task=$jobs[$job['step']];$rows=[];$error=null;$after=null;
            try{$until=WGPP_Analytics::date($task['to'])->modify('+1 day')->format('Y-m-d');
                if($task['metric']==='posts'){$params=['fields'=>'id,message,created_time,permalink_url,insights.metric(post_media_view).period(lifetime)','since'=>$task['from'],'until'=>$until,'limit'=>25];if(!empty($task['after'])){$params['after']=$task['after'];}$body=WGPP_Facebook::get($app,$page['id'].'/published_posts',$params,$page['token']);$rows=self::post_rows($body,$ranges['current']);if(!empty($body['paging']['next'])){$after=$body['paging']['cursors']['after'] ?? null;if(!is_string($after) || !$after || strlen($after)>2048){throw new RuntimeException('Post pagination was incomplete.');}}}
                else{$body=WGPP_Facebook::get($app,$page['id'].'/insights',['metric'=>$task['metric'],'period'=>'day','since'=>$task['from'],'until'=>$until,'limit'=>100],$page['token']);$rows=self::parse($body,$task['from'],$task['to'],$task['metric']);}
            }catch(RuntimeException $e){$error=$e->getMessage();}
            $done=WGPP_Native_Reviews::locked($company,static function()use($company,$saved,$key,$job,$task,$rows,$jobs,$app,$error,$after){if(get_post_meta($company,WGPP_Facebook::PAGE,true)!==$saved || WGPP_Facebook::signature(WGPP_Facebook::app())!==WGPP_Facebook::signature($app)){throw new RuntimeException('Facebook connection changed. Reopen the report.');}$cache=get_post_meta($company,WGPP_Facebook::CACHE,true) ?: [];if(($cache[$key]['step'] ?? -1)!==$job['step']){return null;}$entry=$cache[$key];if($error){$entry['errors'][$task['metric']]=$error;}elseif($task['metric']==='posts'){$entry['posts']=array_replace($entry['posts'],$rows);if($after){$seen=array_column($entry['jobs'],'after');if(count(array_filter($entry['jobs'],static function($t){return $t['metric']==='posts';}))>=20 || count($entry['posts'])>=500 || in_array($after,$seen,true)){$entry['posts_incomplete']=true;}else{$next=$task;$next['after']=$after;$entry['jobs'][]=$next;}}}else{$entry['series'][$task['metric']][$task['side']]=array_replace($entry['series'][$task['metric']][$task['side']] ?? [],$rows);}$entry['step']++;$entry['updated']=time();$entry['status']=$entry['step']===count($entry['jobs'])?'complete':'queued';$cache[$key]=$entry;WGPP_Facebook::save_meta($company,WGPP_Facebook::CACHE,$cache);return $entry;});
            return $done && $done['status']==='complete'?self::result($done):['status'=>'queued','step'=>$job['step']+1,'steps'=>count($done['jobs'] ?? $jobs)];
        }catch(RuntimeException $e){WGPP_Native_Reviews::locked($company,static function()use($company,$key,$e){$cache=get_post_meta($company,WGPP_Facebook::CACHE,true) ?: [];if(isset($cache[$key])){$cache[$key]['status']='failed';$cache[$key]['message']=$e->getMessage();$cache[$key]['updated']=time();WGPP_Facebook::save_meta($company,WGPP_Facebook::CACHE,$cache);}});return ['status'=>'failed','message'=>$e->getMessage()];}
    }
    public static function ajax(){if(!WGPP_Analytics::allowed()){wp_send_json_error(['message'=>'Company access required.'],403);return;}check_ajax_referer('wgpp_analytics','nonce');nocache_headers();try{$q=[];foreach(['preset','start','end','comparison'] as $key){$v=$_GET[$key] ?? '';if(!is_string($v)){throw new InvalidArgumentException('Invalid Facebook reporting dates.');}$q[$key]=sanitize_text_field(wp_unslash($v));}$ranges=WGPP_Analytics::ranges($q['preset'],$q['end'],$q['start'],$q['comparison']);$c=WGPP_Company::context();$tz=WGPP_GA4::config($c['id'])['timezone'] ?? 'America/Chicago';if($ranges['current'][1]>(new DateTimeImmutable('yesterday',new DateTimeZone($tz)))->format('Y-m-d')){throw new InvalidArgumentException('Select Facebook reporting dates through yesterday.');}wp_send_json_success(self::request($c['id'],$ranges));}catch(InvalidArgumentException $e){wp_send_json_error(['message'=>$e->getMessage()],422);}catch(RuntimeException $e){wp_send_json_error(['message'=>$e->getMessage()],503);}}
}

/** Instagram professional reporting uses the selected Page and its owner's User grant. */
final class WGPP_IG_Reports {
    const ACCOUNT='_wgpp_ig_account_v1';const CACHE='_wgpp_ig_reports_v1';
    public static function total($body,$name){foreach(($body['data'] ?? []) as $m){if(($m['name'] ?? '')===$name){$v=$m['total_value']['value'] ?? null;if(is_numeric($v) && is_finite((float)$v) && $v>=0){return (float)$v;}}}throw new RuntimeException('Instagram did not return '.$name.' for these dates.');}
    public static function growth($body){foreach(($body['data'] ?? []) as $m){if(($m['name'] ?? '')!=='follows_and_unfollows'){continue;}foreach(($m['total_value']['breakdowns'] ?? []) as $b){if(($b['dimension_keys'] ?? [])!==['follow_type']){continue;}$values=[];foreach(($b['results'] ?? []) as $r){$key=rtrim(strtoupper($r['dimension_values'][0] ?? ''),'S');$key=['FOLLOWER'=>'FOLLOW','NON_FOLLOWER'=>'UNFOLLOW'][$key] ?? $key;$v=$r['value'] ?? null;if(in_array($key,['FOLLOW','UNFOLLOW'],true) && is_numeric($v) && is_finite((float)$v) && $v>=0){$values[$key]=(float)$v;}}if(isset($values['FOLLOW'],$values['UNFOLLOW'])){return $values['FOLLOW']-$values['UNFOLLOW'];}}}throw new RuntimeException('Instagram net follower change is unavailable for these dates.');}
    public static function media($body,$range){if(!is_array($body['data'] ?? null)){throw new RuntimeException('Instagram media was not returned.');}$rows=[];$older=false;
        foreach($body['data'] as $post){$id=$post['id'] ?? '';if(!is_string($id) || !preg_match('/^[1-9][0-9]{0,29}$/D',$id) || !is_string($post['timestamp'] ?? null)){throw new RuntimeException('Invalid Instagram media identity or date.');}try{$date=(new DateTimeImmutable($post['timestamp']))->format('Y-m-d');}catch(Exception $e){throw new RuntimeException('Invalid Instagram media timestamp.');}if($date<$range[0]){$older=true;continue;}if($date>$range[1]){continue;}$views=null;foreach(($post['insights']['data'] ?? []) as $m){if(($m['name'] ?? '')==='views' && ($m['period'] ?? '')==='lifetime'){$v=$m['values'][0]['value'] ?? $m['total_value']['value'] ?? null;if(is_numeric($v) && is_finite((float)$v) && $v>=0){$views=(float)$v;}}}$url=$post['permalink'] ?? '';if(parse_url($url,PHP_URL_SCHEME)!=='https' || !in_array(parse_url($url,PHP_URL_HOST),['instagram.com','www.instagram.com'],true)){$url='';}$rows[$id]=['id'=>$id,'date'=>$date,'text'=>WGPP_FB_Reports::excerpt($post['caption'] ?? 'Instagram post'),'url'=>$url,'views'=>$views];}
        return ['rows'=>$rows,'older'=>$older];
    }
    public static function result($job){$out=['status'=>'complete','page'=>'@'.$job['name'],'ranges'=>$job['ranges'],'collected_at'=>gmdate('c',$job['updated']),'errors'=>$job['errors'],'instagram'=>true];
        foreach(['current','comparison'] as $side){if(!$job['ranges'][$side]){$out[$side]=null;continue;}$expected=count(WGPP_FB_Reports::chunks([$side=>$job['ranges'][$side]]));$views=$job['views'][$side] ?? [];$net=$job['growth'][$side] ?? [];$out[$side]=['views'=>['total'=>count($views)===$expected?array_sum($views):null],'followers'=>['total'=>$side==='current'?($job['followers'] ?? null):null,'net'=>count($net)===$expected?array_sum($net):null,'change'=>null]];}
        $a=$out['current']['views']['total'];$b=$out['comparison']['views']['total'] ?? null;$out['change']=$a!==null && $b!==null?WGPP_Analytics::percent($a,$b):null;$posts=array_values($job['posts']);$valid=array_values(array_filter($posts,static function($p){return $p['views']!==null;}));usort($valid,static function($a,$b){return ($b['views']<=>$a['views']) ?: strcmp($a['id'],$b['id']);});$out['posts']=['top'=>array_slice($valid,0,5),'lower'=>array_slice(array_reverse(array_slice($valid,5)),0,5),'engagement_basis'=>'Engagement actions are not supplied; views measure visibility, not reactions, comments, shares or saves.','count'=>count($posts),'ranked'=>count($valid),'complete'=>empty($job['incomplete']) && empty($job['errors']['posts']) && count($valid)===count($posts)];return $out;
    }
    public static function request($company,$ranges){
        if(!WGPP_Company::can('view') || (int)(WGPP_Company::context()['id'] ?? 0)!==(int)$company){throw new RuntimeException('Company access required.');}$saved=get_post_meta($company,self::ACCOUNT,true);if(!$saved){return ['status'=>'not_connected','message'=>'Connect Instagram under Account → Connections.'];}$ig=WGPP_Facebook::decrypt($saved,'company:'.$company.':instagram');$app=WGPP_Facebook::app();$authSaved=get_post_meta($company,WGPP_Facebook::AUTH,true);$auth=WGPP_Facebook::decrypt($authSaved ?: '','company:'.$company.':auth');if($auth['expires']<time()+60 || $ig['auth']!==hash('sha256',$authSaved) || $auth['app']!==WGPP_Facebook::signature($app)){throw new RuntimeException('Reconnect Meta and select Instagram again.');}
        foreach($ranges as $r){if($r){$n=(int)WGPP_Analytics::date($r[0])->diff(WGPP_Analytics::date($r[1]))->format('%r%a');if($n<0 || $n>365){throw new RuntimeException('Select up to one year per Instagram reporting period.');}}}
        $key=hash('sha256',wp_json_encode($ranges).$ig['auth'].'|instagram-v4');$job=WGPP_Native_Reviews::locked($company,static function()use($company,$key,$ranges,$ig){$cache=get_post_meta($company,self::CACHE,true) ?: [];$entry=$cache[$key] ?? null;if($entry && $entry['status']==='complete' && $entry['updated']>time()-(empty($entry['errors'])?21600:300)){return ['done'=>$entry];}if($entry && $entry['status']==='processing' && $entry['updated']>time()-60){return null;}if(!$entry || $entry['updated']<time()-21600 || $entry['status']==='complete'){$tasks=[['type'=>'profile']];foreach(['views','growth'] as $type){foreach(WGPP_FB_Reports::chunks($ranges) as $t){$t['type']=$type;$tasks[]=$t;}}$tasks[]=['type'=>'posts'];$entry=['step'=>0,'tasks'=>$tasks,'ranges'=>$ranges,'name'=>$ig['username'],'posts'=>[],'errors'=>[]];}if(count($cache)>=12 && !isset($cache[$key])){uasort($cache,static function($a,$b){return $a['updated']<=>$b['updated'];});unset($cache[array_key_first($cache)]);}$entry['status']='processing';$entry['updated']=time();$cache[$key]=$entry;WGPP_Facebook::save_meta($company,self::CACHE,$cache);return $entry;});
        if($job===null){return ['status'=>'queued'];}if(isset($job['done'])){return self::result($job['done']);}$task=$job['tasks'][$job['step']];$error=null;$data=null;$after=null;$older=false;
        try{if($task['type']==='profile'){$data=WGPP_Facebook::get($app,$ig['id'],['fields'=>'id,username,followers_count'],$auth['token']);$v=$data['followers_count'] ?? null;if(($data['id'] ?? '')!==$ig['id'] || !is_numeric($v) || !is_finite((float)$v) || $v<0){throw new RuntimeException('Instagram follower total is unavailable.');}$data=(float)$v;}
            elseif($task['type']==='posts'){$params=['fields'=>'id,caption,timestamp,permalink,insights.metric(views)','limit'=>25];if(!empty($task['after'])){$params['after']=$task['after'];}$body=WGPP_Facebook::get($app,$ig['id'].'/media',$params,$auth['token']);$parsed=self::media($body,$ranges['current']);$data=$parsed['rows'];$older=$parsed['older'];if(!empty($body['paging']['next']) && !$older){$after=$body['paging']['cursors']['after'] ?? null;if(!is_string($after) || !$after || strlen($after)>2048){throw new RuntimeException('Instagram media pagination is incomplete.');}}}
            else{$params=['metric'=>$task['type']==='views'?'views':'follows_and_unfollows','metric_type'=>'total_value','period'=>'day','since'=>WGPP_Analytics::date($task['from'])->getTimestamp(),'until'=>WGPP_Analytics::date($task['to'])->modify('+1 day')->getTimestamp()-1];if($task['type']==='growth'){$params['breakdown']='follow_type';}$body=WGPP_Facebook::get($app,$ig['id'].'/insights',$params,$auth['token']);$data=$task['type']==='views'?self::total($body,'views'):self::growth($body);}
        }catch(RuntimeException $e){$error=$e->getMessage();}
        $done=WGPP_Native_Reviews::locked($company,static function()use($company,$key,$job,$task,$error,$data,$after,$saved,$authSaved,$app){if(get_post_meta($company,self::ACCOUNT,true)!==$saved || get_post_meta($company,WGPP_Facebook::AUTH,true)!==$authSaved || WGPP_Facebook::signature(WGPP_Facebook::app())!==WGPP_Facebook::signature($app)){throw new RuntimeException('Instagram connection changed. Reopen the report.');}$cache=get_post_meta($company,self::CACHE,true) ?: [];if(($cache[$key]['step'] ?? -1)!==$job['step']){return null;}$entry=$cache[$key];if($error){$entry['errors'][$task['type']]=$error;}elseif($task['type']==='profile'){$entry['followers']=$data;}elseif($task['type']==='posts'){$entry['posts']=array_replace($entry['posts'],$data);if($after){$pages=count(array_filter($entry['tasks'],static function($t){return $t['type']==='posts';}));if($pages>=20 || in_array($after,array_column($entry['tasks'],'after'),true)){$entry['incomplete']=true;}else{$next=$task;$next['after']=$after;$entry['tasks'][]=$next;}}}else{$entry[$task['type']][$task['side']][$task['from']]=$data;}$entry['step']++;$entry['updated']=time();$entry['status']=$entry['step']===count($entry['tasks'])?'complete':'queued';$cache[$key]=$entry;WGPP_Facebook::save_meta($company,self::CACHE,$cache);return $entry;});return $done && $done['status']==='complete'?self::result($done):['status'=>'queued','step'=>$job['step']+1,'steps'=>count($done['tasks'] ?? $job['tasks'])];
    }
    public static function ajax(){if(!WGPP_Analytics::allowed()){wp_send_json_error(['message'=>'Company access required.'],403);return;}check_ajax_referer('wgpp_analytics','nonce');nocache_headers();try{$q=[];foreach(['preset','start','end','comparison'] as $key){$v=$_GET[$key] ?? '';if(!is_string($v)){throw new InvalidArgumentException('Invalid Instagram dates.');}$q[$key]=sanitize_text_field(wp_unslash($v));}$ranges=WGPP_Analytics::ranges($q['preset'],$q['end'],$q['start'],$q['comparison']);if($ranges['current'][1]>(new DateTimeImmutable('yesterday',new DateTimeZone('America/Chicago')))->format('Y-m-d')){throw new InvalidArgumentException('Select dates through yesterday.');}$c=WGPP_Company::context();wp_send_json_success(self::request($c['id'],$ranges));}catch(InvalidArgumentException $e){wp_send_json_error(['message'=>$e->getMessage()],422);}catch(RuntimeException $e){wp_send_json_error(['message'=>$e->getMessage()],503);}}
}
